package cn.kaoyan.assistant;
public class PageRasterSizeTest {static void check(boolean b,String m){if(!b)throw new AssertionError(m);}public static void main(String[] x){int[][] samples={{595,842,1600},{842,595,2400},{1,100000,2400},{100000,1,2400},{100000,100000,2400}};for(int[] s:samples){PageRasterSize r=PageRasterSize.fit(s[0],s[1],s[2]);check(r.width>0&&r.height>0,"empty render");check((long)r.width*r.height<=4000000,"memory budget exceeded");check(r.width<=2400&&r.height<=8192,"oversized dimension");}PageRasterSize a=PageRasterSize.fit(595,842,1200);check(Math.abs(a.width/(double)a.height-595.0/842)<.002,"page shape changed");try{PageRasterSize.fit(0,842,1200);throw new AssertionError("zero page accepted");}catch(IllegalArgumentException expected){}System.out.println("PDF raster memory, dimensions and aspect ratio checked");}}
